package com.fitconnect.bookingservice;
import org.junit.jupiter.api.Test; import java.time.LocalDateTime; import java.util.*; import static org.junit.jupiter.api.Assertions.*; import static org.mockito.Mockito.*;
class BookingSchedulerTest {@Test void shouldCancelExpiredBookings(){BookingRepository repo=mock(BookingRepository.class);ClassClient classes=mock(ClassClient.class);NotificationClient notifications=mock(NotificationClient.class);Booking b=Booking.builder().id(1L).userId(1L).userEmail("a@b.fr").classId(2L).numberOfSpots(2).bookingReference("BK-X").status(Booking.Status.PENDING_PAYMENT).paymentDeadline(LocalDateTime.now().minusMinutes(1)).build();when(repo.findByStatusAndPaymentDeadlineBefore(eq(Booking.Status.PENDING_PAYMENT),any())).thenReturn(List.of(b));new BookingScheduler(repo,classes,notifications).expirePayments();assertEquals(Booking.Status.CANCELLED,b.getStatus());verify(classes).decrement(2L,2);}}
